// Existing SQL monitor catalog remains byte-identical when the DEV NAT
// reporter is added. Each group retains its own content-derived catalog ID.
public ServiceCatalog CatalogFor(CorrelationKey key) {
    var monitor = Monitors.Single(m => m.Key == key);
    if (!Monitors.Any(m => m.Id == "nat-a-egress")) return Catalog();
    var selected = monitor.Id == "nat-a-egress"
        ? Monitors.Where(m => m.Id == "nat-a-egress").ToImmutableArray()
        : Monitors.Where(m => m.Id != "nat-a-egress").ToImmutableArray();
    if (selected.Any(m => !m.Dependencies.IsDefaultOrEmpty))
        throw new ArgumentException("Independent catalog groups cannot acquire cross-group dependencies.");
    return (this with { Monitors = selected }).Catalog();
}
